// AL FAHD - Generate crawlable static property pages and sitemap from Firestore.
import { mkdir, readdir, readFile, rm, writeFile } from "node:fs/promises";

const projectId = "al-fahd-real-estate";
const apiKey = process.env.FIREBASE_API_KEY || "AIzaSyBzyKd-sFJzeZMQsxaJaeuA_tQxNOMRtAs";
const site = "https://fhdmsraby-lgtm.github.io/al-fahd-real-estate/";
const collectionUrl = "https://firestore.googleapis.com/v1/projects/" + projectId + "/databases/(default)/documents/properties";
const hiddenStatus = /قيد المراجعة|معلق|مرفوض|مسودة|مسوده|مباع|تم البيع|مؤجر|تم التأجير|غير متاح|متوقف|محجوز|تم حجز/i;
const generatedMarker = "<!-- Generated by scripts/generate-sitemap.mjs -->";

function decodeValue(v) {
  if (!v || typeof v !== "object") return "";
  if ("stringValue" in v) return v.stringValue;
  if ("integerValue" in v) return Number(v.integerValue);
  if ("doubleValue" in v) return v.doubleValue;
  if ("booleanValue" in v) return v.booleanValue;
  if ("timestampValue" in v) return v.timestampValue;
  if ("nullValue" in v) return null;
  if ("referenceValue" in v) return v.referenceValue;
  if ("geoPointValue" in v) return v.geoPointValue;
  if ("arrayValue" in v) return (v.arrayValue.values || []).map(decodeValue);
  if ("mapValue" in v) return decodeFields(v.mapValue.fields || {});
  if ("bytesValue" in v) return v.bytesValue;
  return "";
}
function decodeFields(fields) {
  const out = {};
  for (const [key, value] of Object.entries(fields || {})) out[key] = decodeValue(value);
  return out;
}
function escapeHtml(value) {
  return String(value ?? "").replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;").replaceAll("'", "&#39;");
}
function safeUrl(value) {
  const s = String(value || "").trim();
  return /^https:\/\/|^http:\/\/|^data:image\/(png|jpe?g|webp|gif);base64,/i.test(s) ? s : "";
}
function isPublic(p) {
  const status = String(p.status || "متاح");
  if (hiddenStatus.test(status)) return false;
  const approved = p.approved;
  if (approved === false || approved === 0 || approved === "pending" || approved === "قيد المراجعة" || approved === "مرفوض") return false;
  return true;
}
function dateOnly(value) {
  const d = value ? new Date(value) : new Date();
  return Number.isNaN(d.getTime()) ? new Date().toISOString().slice(0, 10) : d.toISOString().slice(0, 10);
}
function numericPrice(value) {
  const n = Number(String(value ?? "").replace(/,/g, "").replace(/[^\d.]/g, ""));
  return Number.isFinite(n) && n > 0 ? n : null;
}
function propertyPage(id, p) {
  const title = String(p.title || "عقار للبيع أو الإيجار في القاهرة");
  const city = String(p.city || p.area || "القاهرة");
  const address = String(p.address || "");
  const priceText = String(p.price ?? "السعر عند التواصل");
  const details = String(p.details || p.description || title);
  const type = String(p.type || p.dealType || "عقار");
  const rooms = p.rooms ?? "-";
  const baths = p.baths ?? "-";
  const area = p.area ?? "-";
  const images = (Array.isArray(p.images) ? p.images : []).map(safeUrl).filter(Boolean);
  if (!images.length && p.image) {
    const image = safeUrl(p.image);
    if (image) images.push(image);
  }
  const canonical = site + "properties/" + encodeURIComponent(id) + "/";
  const seoTitle = [title.slice(0, 35), city, "مكتب الفهد"].filter(Boolean).join(" | ").slice(0, 60);
  const description = ("عقار " + type + " في " + city + " بسعر " + priceText + " جنيه. " + title.slice(0, 55) + " - مكتب الفهد للعقارات وواتساب 01040872120.").slice(0, 155);
  const price = numericPrice(priceText);
  const schema = {
    "@context": "https://schema.org",
    "@type": "RealEstateListing",
    "name": title,
    "description": details,
    "url": canonical,
    "image": images,
    "address": {
      "@type": "PostalAddress",
      "addressLocality": city,
      "streetAddress": address,
      "addressCountry": "EG"
    },
    "offers": {
      "@type": "Offer",
      ...(price ? { "price": price } : {}),
      "priceCurrency": "EGP",
      "availability": "https://schema.org/InStock"
    },
    "numberOfRooms": Number(rooms) || undefined,
    "numberOfBathroomsTotal": Number(baths) || undefined,
    "floorSize": Number(area) ? { "@type": "QuantitativeValue", "value": Number(area), "unitCode": "MTK" } : undefined
  };
  const jsonLd = JSON.stringify(schema).replace(/</g, "\\u003c");
  const imageHtml = images.map((src, i) => '<img src="' + escapeHtml(src) + '" alt="' + escapeHtml(title) + ' - صورة ' + (i + 1) + '" loading="lazy">').join("\n");
  const status = String(p.status || "متاح");
  return generatedMarker + '\n<!doctype html>\n<html lang="ar" dir="rtl">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>' + escapeHtml(seoTitle) + '</title>\n<meta name="description" content="' + escapeHtml(description) + '">\n<meta name="robots" content="index,follow">\n<link rel="canonical" href="' + escapeHtml(canonical) + '">\n<meta property="og:type" content="article">\n<meta property="og:site_name" content="مكتب الفهد للعقارات">\n<meta property="og:url" content="' + escapeHtml(canonical) + '">\n<meta property="og:title" content="' + escapeHtml(seoTitle) + '">\n<meta property="og:description" content="' + escapeHtml(description) + '">\n' + (images[0] ? '<meta property="og:image" content="' + escapeHtml(images[0]) + '">' : '') + '\n<script type="application/ld+json">' + jsonLd + '</scr' + 'ipt>\n<style>body{margin:0;background:#0a0a0a;color:#f7f7f7;font-family:Tahoma,Arial,sans-serif;line-height:1.8}.wrap{max-width:820px;margin:auto;padding:18px}.top{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;border-bottom:2px solid #d4af37;padding-bottom:14px}.brand{color:#d4af37;font-weight:900}.card{background:#171717;border:1px solid #333;border-radius:16px;padding:18px;margin-top:18px}h1{color:#d4af37;font-size:27px}.price{font-size:25px;color:#d4af37;font-weight:900}.muted{color:#bbb}.facts{display:flex;gap:12px;flex-wrap:wrap;margin:14px 0}.fact{background:#242424;padding:7px 12px;border-radius:9px}img{display:block;width:100%;height:auto;max-height:560px;object-fit:cover;border-radius:12px;margin:12px 0}.btn{display:inline-block;text-decoration:none;padding:11px 16px;border-radius:9px;font-weight:bold;margin:6px 4px}.gold{background:#d4af37;color:#111}.green{background:#16a34a;color:white}</style>\n</head>\n<body><main class="wrap">\n<header class="top"><div class="brand">AL FAHD REAL ESTATE<br><span class="muted">مكتب الفهد للعقارات</span></div><a class="btn gold" href="' + site + '">العودة للموقع</a></header>\n<article class="card">\n<h1>' + escapeHtml(title) + '</h1>\n<p class="muted">الموقع: ' + escapeHtml(city) + (address ? ' - ' + escapeHtml(address) : '') + '</p>\n<div class="price">' + escapeHtml(priceText) + ' جنيه</div>\n<div class="facts"><span class="fact">النوع: ' + escapeHtml(type) + '</span><span class="fact">الغرف: ' + escapeHtml(rooms) + '</span><span class="fact">الحمامات: ' + escapeHtml(baths) + '</span><span class="fact">المساحة: ' + escapeHtml(area) + ' م²</span></div>\n<p>' + escapeHtml(details).replace(/\r?\n/g, "<br>") + '</p>\n' + imageHtml + '\n<p>الحالة: ' + escapeHtml(status) + '</p>\n<button class="btn gold" type="button" onclick="copyStaticPropertyLink()">📋 نسخ رابط الشقة</button>\n<a class="btn green" href="https://wa.me/201040872120?text=' + encodeURIComponent("أريد الاستفسار عن العقار: " + title + " - " + canonical) + '">تواصل عبر واتساب 01040872120</a>\n<a class="btn gold" href="tel:+201040872120">اتصال بالمكتب</a>\n<p id="copyFeedback" class="muted" aria-live="polite"></p>\n<script>async function copyStaticPropertyLink(){const u=location.href.split("#")[0];const m=document.getElementById("copyFeedback");try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(u)}else{const t=document.createElement("textarea");t.value=u;t.style.position="fixed";t.style.opacity="0";document.body.appendChild(t);t.select();const ok=document.execCommand("copy");t.remove();if(!ok)throw new Error("copy failed")}m.textContent="تم نسخ رابط الشقة بنجاح"}catch(e){m.textContent="انسخ الرابط يدوياً: "+u}}</script>\n</article></main></body></html>\n';
}

async function fetchAllProperties() {
  const docs = [];
  let pageToken = "";
  do {
    const url = new URL(collectionUrl);
    url.searchParams.set("pageSize", "1000");
    url.searchParams.set("key", apiKey);
    if (pageToken) url.searchParams.set("pageToken", pageToken);
    const response = await fetch(url);
    if (!response.ok) throw new Error("Firestore read failed (" + response.status + "): " + (await response.text()).slice(0, 600));
    const data = await response.json();
    for (const doc of data.documents || []) {
      const id = doc.name.split("/").pop();
      if (!/^[A-Za-z0-9_-]+$/.test(id)) throw new Error("Unsupported Firestore document ID: " + id);
      const property = decodeFields(doc.fields || {});
      property._id = id;
      if (isPublic(property)) docs.push({ id, property, lastmod: dateOnly(property.updatedAt || property.createdAt) });
    }
    pageToken = data.nextPageToken || "";
  } while (pageToken);
  if (!docs.length) throw new Error("Firestore returned zero public properties; refusing to overwrite the current sitemap or generated pages.");
  return docs;
}

const properties = await fetchAllProperties();
const today = new Date().toISOString().slice(0, 10);
const generatedRoot = "properties";
await mkdir(generatedRoot, { recursive: true });
for (const entry of await readdir(generatedRoot, { withFileTypes: true })) {
  if (!entry.isDirectory()) continue;
  const file = generatedRoot + "/" + entry.name + "/index.html";
  try {
    const old = await readFile(file, "utf8");
    if (old.startsWith(generatedMarker)) await rm(generatedRoot + "/" + entry.name, { recursive: true, force: true });
  } catch {}
}
const urls = [
  '  <url><loc>' + site + '</loc><lastmod>' + today + '</lastmod><changefreq>daily</changefreq><priority>1.0</priority></url>'
];
for (const { id, property, lastmod } of properties) {
  const dir = generatedRoot + "/" + id;
  await mkdir(dir, { recursive: true });
  await writeFile(dir + "/index.html", propertyPage(id, property), "utf8");
  const loc = site + "properties/" + encodeURIComponent(id) + "/";
  urls.push('  <url><loc>' + escapeHtml(loc) + '</loc><lastmod>' + lastmod + '</lastmod><changefreq>weekly</changefreq><priority>0.8</priority></url>');
}
const urlset = '<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n' + urls.join("\n") + '\n</urlset>\n';
await writeFile("sitemap.xml", urlset, "utf8");
await writeFile("sitemap-index.xml", '<?xml version="1.0" encoding="UTF-8"?>\n<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><sitemap><loc>' + site + 'sitemap.xml</loc><lastmod>' + today + '</lastmod></sitemap></sitemapindex>\n', "utf8");
console.log("Generated " + properties.length + " static property pages and sitemap.xml from Firestore.");
